// Client-side heuristics — one signal, never the decision
fun localRootSignal(context: Context): Boolean = RootBeer(context).isRooted

// The decision lives on the server; the client only applies the policy it gets back
suspend fun trustPolicy(context: Context, requestHash: String): Policy {
  val token = attest(context, requestHash)              // Play Integrity standard request
  return api.evaluateTrust(
    integrityToken = token,
    localSignal = localRootSignal(context)              // advisory input, weighted server-side
  )
}

