// Android 13+ — mark the clip sensitive so the clipboard preview stays blank,
// and clear it ourselves rather than trusting the user to.
fun copyOtp(context: Context, code: String, timeoutMs: Long = 30_000) {
  val cm = context.getSystemService(ClipboardManager::class.java)
  val clip = ClipData.newPlainText("otp", code).apply {
    description.extras = PersistableBundle().apply {
      putBoolean(ClipDescription.EXTRA_IS_SENSITIVE, true)
    }
  }
  cm.setPrimaryClip(clip)
  Handler(Looper.getMainLooper()).postDelayed(
    { cm.setPrimaryClip(ClipData.newPlainText("", "")) }, timeoutMs
  )
}

