// The key is the point: it is unusable until the system authenticates the user
fun createAuthBoundKey(alias: String) {
  val spec = KeyGenParameterSpec.Builder(
    alias, KeyProperties.PURPOSE_ENCRYPT or KeyProperties.PURPOSE_DECRYPT
  )
    .setBlockModes(KeyProperties.BLOCK_MODE_GCM)
    .setEncryptionPaddings(KeyProperties.ENCRYPTION_PADDING_NONE)
    .setUserAuthenticationRequired(true)
    .setUserAuthenticationParameters(0, KeyProperties.AUTH_BIOMETRIC_STRONG)
    .setInvalidatedByBiometricEnrollment(true)   // new fingerprint destroys it, by design
    .build()
  KeyGenerator.getInstance(KeyProperties.KEY_ALGORITHM_AES, "AndroidKeyStore")
    .apply { init(spec) }.generateKey()
}

// Authenticate by using the key, not by trusting a callback's boolean
fun unlockSession(activity: FragmentActivity, blob: EncryptedBlob) {
  val cipher = Cipher.getInstance("AES/GCM/NoPadding").apply {
    init(Cipher.DECRYPT_MODE, keyFor(ALIAS), GCMParameterSpec(128, blob.iv))
  }
  val prompt = BiometricPrompt(
    activity, ContextCompat.getMainExecutor(activity),
    object : BiometricPrompt.AuthenticationCallback() {
      override fun onAuthenticationSucceeded(r: BiometricPrompt.AuthenticationResult) {
        val token = r.cryptoObject!!.cipher!!.doFinal(blob.ciphertext)   // this is the proof
        session.restore(String(token))
      }
      override fun onAuthenticationError(code: Int, msg: CharSequence) {
        if (code == BiometricPrompt.ERROR_LOCKOUT_PERMANENT) fallbackToPassword()
      }
    }
  )
  prompt.authenticate(
    BiometricPrompt.PromptInfo.Builder()
      .setTitle("Unlock")
      .setAllowedAuthenticators(BIOMETRIC_STRONG or DEVICE_CREDENTIAL)
      .build(),
    BiometricPrompt.CryptoObject(cipher)
  )
}
