// Every inbound link is an unauthenticated request from an unknown caller
fun handleLink(uri: Uri): Route? {
  if (uri.scheme != "https") return null            // ❌ myapp:// is claimable by any app
  if (uri.host != "example.com") return null        // allow-list, never a loose match
  val id = uri.pathSegments.getOrNull(1)?.toLongOrNull() ?: return null
  return when (uri.pathSegments.firstOrNull()) {
    "order" -> Route.Order(id)        // resolved here; the server still re-checks ownership
    "pay" -> Route.PayConfirm(id)     // destructive, so it lands on a confirmation screen
    else -> null
  }
}

// Intent redirection: never start what the caller handed you
