// Pick the protection class per file; the default is readable after the first unlock
func writeVault(_ data: Data, to url: URL) throws {
  try data.write(to: url, options: [.atomic, .completeFileProtection])
}

// Keep a file out of iCloud and out of an encrypted local backup
func excludeFromBackup(_ url: URL) throws {
  var url = url
  var values = URLResourceValues()
  values.isExcludedFromBackup = true
  try url.setResourceValues(values)
}

