// Registration: the server issues the challenge, the platform creates the key pair
suspend fun registerPasskey(activity: Activity, optionsJson: String) {
  val request = CreatePublicKeyCredentialRequest(requestJson = optionsJson)
  val response = CredentialManager.create(activity)
    .createCredential(activity, request) as CreatePublicKeyCredentialResponse
  api.finishRegistration(response.registrationResponseJson)  // server verifies, stores pubkey
}

// Sign-in: one sheet for passkeys and for saved passwords during the migration
suspend fun signIn(activity: Activity, challengeJson: String): Session {
  val request = GetCredentialRequest(
    listOf(
      GetPublicKeyCredentialOption(requestJson = challengeJson),
      GetPasswordOption()
    )
  )
  val result = CredentialManager.create(activity).getCredential(activity, request)
  return when (val credential = result.credential) {
    is PublicKeyCredential -> api.verifyAssertion(credential.authenticationResponseJson)
    is PasswordCredential -> api.login(credential.id, credential.password)
    else -> error("unsupported credential type")
  }
}
