// The client buys, hands the identifier over, and then asks what the server says
func purchase(_ product: Product, userId: UUID) async throws -> Entitlement {
  let result = try await product.purchase(options: [.appAccountToken(userId)])
  guard case .success(let verification) = result,
        case .verified(let transaction) = verification else { throw PurchaseError.unverified }
  let entitlement = try await api.claim(originalId: transaction.originalID)   // server decides
  await transaction.finish()
  return entitlement
}

// Renewals, refunds and revocations arrive without the app ever being launched
func listenForStoreUpdates() -> Task<Void, Never> {
  Task.detached {
    for await update in Transaction.updates {
      guard case .verified(let transaction) = update else { continue }
      _ = try? await api.claim(originalId: transaction.originalID)
      await transaction.finish()
    }
  }
}

