// The app holds no vendor key: it calls your backend, which holds it
func summarise(_ text: String) async throws -> String {
  var request = URLRequest(url: URL(string: "https://api.example.com/v1/summarise")!)
  request.httpMethod = "POST"
  request.setValue("Bearer \(await session.accessToken())", forHTTPHeaderField: "Authorization")
  let appCheck = try await AppCheck.appCheck().token(forcingRefresh: false)
  request.setValue(appCheck.token, forHTTPHeaderField: "X-Firebase-AppCheck")
  request.httpBody = try JSONEncoder().encode(["text": text])
  let (data, _) = try await URLSession.shared.data(for: request)
  return try JSONDecoder().decode(SummaryResponse.self, from: data).text
}

